def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w
                            and p not in seen and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        stack.append(p)
            objects.append((color, cells))

    out = [[0] * w for _ in range(h)]
    for color, cells in objects:
        minr = min(r for r, c in cells)
        maxr = max(r for r, c in cells)
        minc = min(c for r, c in cells)
        height = maxr - minr + 1

        if color == 1:
            to_top = minc < w / 2
        elif color == 2:
            to_top = minc >= w / 2
        elif color == 3:
            to_top = minc >= w / 2
        elif color == 8:
            to_top = minr < h / 2
        else:
            to_top = minr >= h / 2

        new_minr = 0 if to_top else h - height
        for r, c in cells:
            out[new_minr + r - minr][c] = color

    return out
